#!/bin/bash
# multi-instance.sh — Aggregate costs across multiple OpenClaw instances
# Usage: bash multi-instance.sh [instances-config]
# Config file: ~/.openclaw/instances.json

set -euo pipefail

INSTANCES_FILE="${1:-$HOME/.openclaw/instances.json}"
BOLD='\033[1m'
GREEN='\033[0;32m'
RED='\033[0;31m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
NC='\033[0m'

echo -e "${BOLD}╔══════════════════════════════════════════╗${NC}"
echo -e "${BOLD}║     Multi-Instance Cost Aggregator       ║${NC}"
echo -e "${BOLD}╚══════════════════════════════════════════╝${NC}"
echo ""

if [ ! -f "$INSTANCES_FILE" ]; then
  echo -e "${YELLOW}No instances config found at $INSTANCES_FILE${NC}"
  echo ""
  echo "Create it with this format:"
  echo ""
  cat << 'EXAMPLE'
{
  "instances": [
    {
      "name": "personal",
      "url": "http://localhost:3578",
      "token": "your-gateway-token",
      "description": "Personal assistant"
    },
    {
      "name": "work-vps",
      "url": "https://myclaw.example.com:3578",
      "token": "gateway-token-for-vps",
      "description": "Work coding assistant"
    },
    {
      "name": "local",
      "configPath": "/root/.openclaw/openclaw.json",
      "logPath": "/data/.openclaw/logs/openclaw.log",
      "description": "This instance (local access)"
    }
  ]
}
EXAMPLE
  echo ""
  echo "Instances can be remote (url + token) or local (configPath + logPath)."
  echo "Save to: $INSTANCES_FILE"
  exit 0
fi

node -e "
const fs = require('fs');
const https = require('https');
const http = require('http');

const config = JSON.parse(fs.readFileSync('$INSTANCES_FILE', 'utf8'));
const instances = config.instances || [];

const costs = {
  'claude-opus-4-6': 0.71, 'claude-sonnet-4-6': 0.53, 'claude-haiku-4-5': 0.15,
  'gpt-5.2': 0.44, 'deepseek-v3.2': 0.04, 'minimax-m2.5': 0.04,
  'gemini-flash-latest': 0.04, 'grok-4': 0.50,
};

async function fetchRemote(url, token) {
  return new Promise((resolve) => {
    const parsed = new URL(url + '/api/config');
    const mod = parsed.protocol === 'https:' ? https : http;
    const req = mod.get({
      hostname: parsed.hostname,
      port: parsed.port,
      path: parsed.pathname,
      headers: { 'Authorization': 'Bearer ' + token },
      timeout: 10000,
    }, (res) => {
      let data = '';
      res.on('data', d => data += d);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch(e) { resolve(null); }
      });
    });
    req.on('error', () => resolve(null));
    req.on('timeout', () => { req.destroy(); resolve(null); });
  });
}

function analyzeLocal(configPath, logPath) {
  try {
    const raw = fs.readFileSync(configPath, 'utf8');
    const config = new Function('return (' + raw + ')')();
    const d = config.agents?.defaults || {};
    const m = d.model;
    const primary = typeof m === 'string' ? m : m?.primary || 'unknown';
    const hb = d.heartbeat || {};

    const pName = primary.split('/').pop();
    const pCost = costs[pName] || 0.50;
    const hbModel = (hb.model || primary).split('/').pop();
    const hbCost = costs[hbModel] || 0.04;
    const hbMins = parseInt(hb.every) || 30;
    const hbPerDay = (24 * 60) / hbMins;

    return {
      primary: pName,
      primaryCost: pCost,
      heartbeatModel: hbModel,
      heartbeatCost: hbCost * hbPerDay,
      estimatedDailyReqs: 50,
      estimatedDailyCost: pCost * 50 + hbCost * hbPerDay,
      status: 'ok',
    };
  } catch(e) {
    return { status: 'error', error: e.message };
  }
}

async function run() {
  let grandTotal = 0;
  const results = [];

  for (const inst of instances) {
    process.stderr.write('Checking ' + inst.name + '...\n');

    let data;
    if (inst.configPath) {
      data = analyzeLocal(inst.configPath, inst.logPath);
    } else if (inst.url && inst.token) {
      const remote = await fetchRemote(inst.url, inst.token);
      if (remote) {
        // Parse remote config similar to local
        const d = remote.agents?.defaults || {};
        const m = d.model;
        const primary = (typeof m === 'string' ? m : m?.primary || 'unknown').split('/').pop();
        const pCost = costs[primary] || 0.50;
        data = {
          primary,
          primaryCost: pCost,
          estimatedDailyCost: pCost * 50,
          status: 'ok',
        };
      } else {
        data = { status: 'unreachable' };
      }
    } else {
      data = { status: 'no access configured' };
    }

    results.push({ ...inst, ...data });
  }

  console.log('  ' + 'INSTANCE'.padEnd(18) + 'MODEL'.padEnd(20) + 'DAILY EST'.padEnd(14) + 'MONTHLY EST'.padEnd(14) + 'STATUS');
  console.log('  ' + '─'.repeat(18) + '─'.repeat(20) + '─'.repeat(14) + '─'.repeat(14) + '─'.repeat(14));

  for (const r of results) {
    if (r.status === 'ok') {
      const daily = r.estimatedDailyCost || 0;
      const monthly = daily * 30;
      grandTotal += monthly;
      console.log('  ' + r.name.padEnd(18) + (r.primary || '?').padEnd(20) + ('\$' + daily.toFixed(2)).padEnd(14) + ('\$' + monthly.toFixed(0)).padEnd(14) + '✅ OK');
    } else {
      console.log('  ' + r.name.padEnd(18) + '-'.padEnd(20) + '-'.padEnd(14) + '-'.padEnd(14) + '❌ ' + r.status);
    }
  }

  console.log('');
  console.log('  ' + ''.padEnd(38) + 'TOTAL'.padEnd(14) + '\$' + grandTotal.toFixed(0) + '/month');

  // Find the most expensive
  const sorted = results.filter(r => r.status === 'ok').sort((a, b) => (b.estimatedDailyCost || 0) - (a.estimatedDailyCost || 0));
  if (sorted.length > 1) {
    console.log('');
    console.log('  🔴 Most expensive: ' + sorted[0].name + ' (\$' + (sorted[0].estimatedDailyCost * 30).toFixed(0) + '/month on ' + sorted[0].primary + ')');
    if (sorted[0].primaryCost > 0.20) {
      console.log('     Switching to DeepSeek would save ~\$' + ((sorted[0].primaryCost - 0.04) * 50 * 30).toFixed(0) + '/month on this instance alone');
    }
  }
}

run().catch(e => console.error(e));
" 2>&1 | grep -v "^Checking "

/**
 * parse-config.js — Parse OpenClaw JSON5 config and extract a value
 * Usage: node parse-config.js <config-path> <dot.path> [default-value]
 * 
 * Handles JSON5/JS object literal configs (unquoted keys, trailing commas, 
 * single-quoted strings, comments)
 */

const fs = require('fs');

const configPath = process.argv[2];
const dotPath = process.argv[3];
const defaultVal = process.argv[4] || '';

if (!configPath || !dotPath) {
  console.error('Usage: node parse-config.js <config-path> <dot.path> [default]');
  process.exit(1);
}

try {
  const raw = fs.readFileSync(configPath, 'utf8');
  // Evaluate as JS object literal — handles JSON5, trailing commas, unquoted keys, etc.
  const config = new Function('return (' + raw + ')')();

  // Navigate dot path
  let val = config;
  for (const key of dotPath.split('.')) {
    if (val === undefined || val === null) break;
    val = val[key];
  }

  if (val === undefined || val === null) {
    console.log(defaultVal);
  } else if (typeof val === 'object') {
    console.log(JSON.stringify(val));
  } else {
    console.log(val);
  }
} catch (e) {
  console.error(`Error: ${e.message}`);
  console.log(defaultVal);
}

#!/bin/bash
# preset-manager.sh — Export, import, and manage named config presets
# Usage: bash preset-manager.sh <export|import|list> [args]

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
CONFIG="${HOME}/.openclaw/openclaw.json"
PRESETS_DIR="${HOME}/.openclaw/workspace/skills/cost-optimizer/presets"
ACTION="${1:-list}"
BOLD='\033[1m'
GREEN='\033[0;32m'
RED='\033[0;31m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
NC='\033[0m'

mkdir -p "$PRESETS_DIR"

case "$ACTION" in
  export)
    NAME="${2:-}"
    DESC="${3:-Custom preset}"

    if [ -z "$NAME" ]; then
      echo "Usage: bash preset-manager.sh export <name> [description]"
      exit 1
    fi

    PRESET_FILE="$PRESETS_DIR/${NAME}.preset.json"

    node -e "
const fs = require('fs');
const raw = fs.readFileSync('$CONFIG', 'utf8');
const config = new Function('return (' + raw + ')')();
const d = config.agents?.defaults || {};
const m = d.model;

const preset = {
  name: '$NAME',
  description: '$DESC',
  author: require('os').hostname(),
  version: '5.0.0',
  created: new Date().toISOString(),
  config: {
    model: {
      primary: typeof m === 'string' ? m : m?.primary,
      fallbacks: typeof m === 'object' ? (m.fallbacks || []) : [],
    },
    heartbeat: {
      every: d.heartbeat?.every || null,
      model: d.heartbeat?.model || null,
      target: d.heartbeat?.target || null,
    },
    compaction: {
      memoryFlush: d.compaction?.memoryFlush || {},
    },
    maxConcurrent: d.maxConcurrent || null,
    subagentsMaxConcurrent: d.subagents?.maxConcurrent || null,
    aliases: d.models || {},
  },
};

fs.writeFileSync('$PRESET_FILE', JSON.stringify(preset, null, 2));
console.log('Preset exported: $PRESET_FILE');
console.log('');
console.log(JSON.stringify(preset, null, 2));
" 2>/dev/null

    echo -e "${GREEN}✅ Preset '${NAME}' exported to ${PRESET_FILE}${NC}"
    ;;

  import)
    PRESET_FILE="${2:-}"

    if [ -z "$PRESET_FILE" ] || [ ! -f "$PRESET_FILE" ]; then
      echo "Usage: bash preset-manager.sh import <preset-file.json>"
      echo ""
      echo "Available presets:"
      ls "$PRESETS_DIR"/*.preset.json 2>/dev/null | while read f; do
        NAME=$(node -e "console.log(JSON.parse(require('fs').readFileSync('$f','utf8')).name)" 2>/dev/null)
        DESC=$(node -e "console.log(JSON.parse(require('fs').readFileSync('$f','utf8')).description)" 2>/dev/null)
        echo "  $f"
        echo "    Name: $NAME — $DESC"
      done
      exit 0
    fi

    echo -e "${BOLD}Importing preset...${NC}"

    node -e "
const fs = require('fs');
const preset = JSON.parse(fs.readFileSync('$PRESET_FILE', 'utf8'));

console.log('Name:        ' + preset.name);
console.log('Description: ' + preset.description);
console.log('Author:      ' + (preset.author || '?'));
console.log('Created:     ' + (preset.created || '?'));
console.log('');
console.log('Changes:');
if (preset.config.model?.primary) console.log('  Primary model: ' + preset.config.model.primary);
if (preset.config.model?.fallbacks?.length) console.log('  Fallbacks: ' + preset.config.model.fallbacks.join(', '));
if (preset.config.heartbeat?.every) console.log('  Heartbeat: ' + preset.config.heartbeat.model + ' every ' + preset.config.heartbeat.every);
if (preset.config.maxConcurrent) console.log('  Concurrency: ' + preset.config.maxConcurrent);
console.log('');

// Generate config patch
const patch = { agents: { defaults: {} } };
if (preset.config.model) patch.agents.defaults.model = preset.config.model;
if (preset.config.heartbeat?.every) patch.agents.defaults.heartbeat = preset.config.heartbeat;
if (preset.config.compaction) patch.agents.defaults.compaction = preset.config.compaction;
if (preset.config.maxConcurrent) patch.agents.defaults.maxConcurrent = preset.config.maxConcurrent;
if (preset.config.subagentsMaxConcurrent) {
  patch.agents.defaults.subagents = { maxConcurrent: preset.config.subagentsMaxConcurrent };
}
if (preset.config.aliases && Object.keys(preset.config.aliases).length) {
  patch.agents.defaults.models = preset.config.aliases;
}

const patchFile = '/tmp/preset-import-patch.json';
fs.writeFileSync(patchFile, JSON.stringify(patch, null, 2));
console.log('Config patch generated: ' + patchFile);
console.log('');
console.log('To apply, tell your agent:');
console.log('  Apply the config patch from ' + patchFile);
" 2>/dev/null
    ;;

  list)
    echo -e "${BOLD}Available Presets:${NC}"
    echo ""

    # Built-in presets
    echo -e "${CYAN}Built-in (via apply-preset.sh):${NC}"
    echo "  free      — \$0-5/mo, free models only"
    echo "  budget    — \$5-30/mo, DeepSeek default"
    echo "  balanced  — \$30-100/mo, Sonnet default"
    echo "  quality   — \$100+/mo, Opus default, cheap heartbeats"
    echo ""

    # User presets
    PRESET_COUNT=$(ls "$PRESETS_DIR"/*.preset.json 2>/dev/null | wc -l)
    if [ "$PRESET_COUNT" -gt 0 ]; then
      echo -e "${CYAN}Custom presets:${NC}"
      ls "$PRESETS_DIR"/*.preset.json 2>/dev/null | while read f; do
        node -e "
const p = JSON.parse(require('fs').readFileSync('$f','utf8'));
console.log('  ' + p.name.padEnd(14) + '— ' + p.description + ' (by ' + (p.author||'?') + ', ' + (p.created||'?').substring(0,10) + ')');
" 2>/dev/null
      done
    else
      echo -e "${YELLOW}No custom presets yet.${NC}"
      echo "  Export current config: bash preset-manager.sh export my-setup 'My optimized config'"
    fi
    echo ""
    echo "Commands:"
    echo "  bash preset-manager.sh export <name> [description]"
    echo "  bash preset-manager.sh import <file.preset.json>"
    echo "  bash preset-manager.sh list"
    ;;

  *)
    echo "Usage: bash preset-manager.sh <export|import|list>"
    ;;
esac

#!/bin/bash
# prompt-tracker.sh — Track system prompt size over time, detect growth
# Usage: bash prompt-tracker.sh [workspace-path] [--snapshot|--report]
# --snapshot: Save current state. --report: Compare to previous snapshots.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
WORKSPACE="${1:-$HOME/.openclaw/workspace}"
MODE="${2:---report}"
TRACKER_DIR="$HOME/.openclaw/prompt-snapshots"
BOLD='\033[1m'
GREEN='\033[0;32m'
RED='\033[0;31m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
NC='\033[0m'

mkdir -p "$TRACKER_DIR"

echo -e "${BOLD}╔══════════════════════════════════════════╗${NC}"
echo -e "${BOLD}║     System Prompt Size Tracker           ║${NC}"
echo -e "${BOLD}╚══════════════════════════════════════════╝${NC}"
echo ""

take_snapshot() {
  local TIMESTAMP=$(date +%Y%m%d-%H%M%S)
  local SNAP_FILE="$TRACKER_DIR/snapshot-${TIMESTAMP}.json"

  node -e "
const fs = require('fs');
const path = require('path');
const workspace = '$WORKSPACE';
const files = ['AGENTS.md','SOUL.md','TOOLS.md','IDENTITY.md','USER.md','HEARTBEAT.md','BOOTSTRAP.md','system.md'];

const snapshot = {
  timestamp: new Date().toISOString(),
  workspace: workspace,
  files: {},
  totalChars: 0,
  totalTokensEst: 0,
  skills: {},
};

for (const f of files) {
  const fp = path.join(workspace, f);
  try {
    const content = fs.readFileSync(fp, 'utf8');
    const chars = content.length;
    const tokens = Math.round(chars / 4);
    snapshot.files[f] = { chars, tokens };
    snapshot.totalChars += chars;
    snapshot.totalTokensEst += tokens;
  } catch(e) {
    // File doesn't exist
  }
}

// Check skills
const skillDir = path.join(workspace, 'skills');
try {
  const skills = fs.readdirSync(skillDir, { withFileTypes: true });
  for (const s of skills) {
    if (s.isDirectory()) {
      const skillMd = path.join(skillDir, s.name, 'SKILL.md');
      try {
        const content = fs.readFileSync(skillMd, 'utf8');
        snapshot.skills[s.name] = { chars: content.length, tokens: Math.round(content.length / 4) };
      } catch(e) {}
    }
  }
} catch(e) {}

fs.writeFileSync('$SNAP_FILE', JSON.stringify(snapshot, null, 2));
console.log(JSON.stringify({ file: '$SNAP_FILE', ...snapshot }));
" 2>/dev/null

  echo -e "${GREEN}✅ Snapshot saved:${NC} $SNAP_FILE"
}

show_report() {
  SNAPSHOTS=($(ls -t "$TRACKER_DIR"/snapshot-*.json 2>/dev/null))

  if [ ${#SNAPSHOTS[@]} -eq 0 ]; then
    echo -e "${YELLOW}No snapshots found. Taking first snapshot now...${NC}"
    echo ""
    take_snapshot
    echo ""
    echo "Run again later to see growth over time."
    return
  fi

  node -e "
const fs = require('fs');
const snapFiles = '${SNAPSHOTS[*]}'.split(' ').filter(Boolean);

if (snapFiles.length === 0) {
  console.log('No snapshots to compare.');
  process.exit(0);
}

const snapshots = snapFiles.map(f => JSON.parse(fs.readFileSync(f, 'utf8'))).reverse();

console.log('  ── Snapshot History (' + snapshots.length + ' snapshots) ──');
console.log('');
console.log('  ' + 'DATE'.padEnd(22) + 'TOTAL CHARS'.padEnd(14) + '~TOKENS'.padEnd(10) + 'FILES'.padEnd(8) + 'CHANGE');
console.log('  ' + '─'.repeat(22) + '─'.repeat(14) + '─'.repeat(10) + '─'.repeat(8) + '─'.repeat(12));

for (let i = 0; i < snapshots.length; i++) {
  const s = snapshots[i];
  const fileCount = Object.keys(s.files).length;
  let change = '';

  if (i > 0) {
    const prev = snapshots[i - 1];
    const diff = s.totalTokensEst - prev.totalTokensEst;
    if (diff > 0) change = '+' + diff + ' tokens';
    else if (diff < 0) change = diff + ' tokens';
    else change = 'no change';
  } else {
    change = 'baseline';
  }

  const date = s.timestamp.substring(0, 19).replace('T', ' ');
  console.log('  ' + date.padEnd(22) + String(s.totalChars).padEnd(14) + ('~' + s.totalTokensEst).padEnd(10) + String(fileCount).padEnd(8) + change);
}

// Detailed diff between newest and oldest
if (snapshots.length >= 2) {
  const oldest = snapshots[0];
  const newest = snapshots[snapshots.length - 1];
  const totalDiff = newest.totalTokensEst - oldest.totalTokensEst;

  console.log('');
  console.log('  ── Growth Analysis ──');
  console.log('');
  console.log('  Period: ' + oldest.timestamp.substring(0, 10) + ' → ' + newest.timestamp.substring(0, 10));
  console.log('  Total change: ' + (totalDiff >= 0 ? '+' : '') + totalDiff + ' tokens (' + ((totalDiff / oldest.totalTokensEst) * 100).toFixed(1) + '%)');

  // Per-file diff
  const allFiles = new Set([...Object.keys(oldest.files), ...Object.keys(newest.files)]);
  const diffs = [];
  for (const f of allFiles) {
    const oldTok = oldest.files[f]?.tokens || 0;
    const newTok = newest.files[f]?.tokens || 0;
    const diff = newTok - oldTok;
    if (diff !== 0) {
      diffs.push({ file: f, old: oldTok, new: newTok, diff });
    }
  }

  if (diffs.length > 0) {
    console.log('');
    console.log('  Files that changed:');
    for (const d of diffs.sort((a, b) => Math.abs(b.diff) - Math.abs(a.diff))) {
      const symbol = d.diff > 0 ? '📈' : '📉';
      console.log('    ' + symbol + ' ' + d.file.padEnd(20) + (d.diff > 0 ? '+' : '') + d.diff + ' tokens (' + d.old + ' → ' + d.new + ')');
    }
  }

  // Cost impact
  if (totalDiff !== 0) {
    console.log('');
    console.log('  Cost impact of growth (at 50 req/day):');
    console.log('    On Opus:    ' + (totalDiff > 0 ? '+' : '') + '\$' + ((totalDiff / 1e6) * 15 * 50 * 30).toFixed(2) + '/month');
    console.log('    On DeepSeek: ' + (totalDiff > 0 ? '+' : '') + '\$' + ((totalDiff / 1e6) * 0.27 * 50 * 30).toFixed(2) + '/month');
  }
}

// Current breakdown
const newest = snapshots[snapshots.length - 1];
console.log('');
console.log('  ── Current File Sizes ──');
console.log('');
for (const [f, data] of Object.entries(newest.files).sort((a, b) => b[1].tokens - a[1].tokens)) {
  const bar = '█'.repeat(Math.min(30, Math.round(data.tokens / 100)));
  console.log('    ' + f.padEnd(20) + ('~' + data.tokens).padEnd(8) + bar);
}
" 2>/dev/null
}

case "$MODE" in
  --snapshot|-s)
    take_snapshot
    ;;
  --report|-r|*)
    show_report
    ;;
esac

#!/bin/bash
# provider-compare.sh — Detect same model across multiple providers, find cheapest route
# Usage: bash provider-compare.sh [config-path]
# Catches the "paying for free stuff" mistake

set -euo pipefail

CONFIG="${1:-$HOME/.openclaw/openclaw.json}"
BOLD='\033[1m'
GREEN='\033[0;32m'
RED='\033[0;31m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
NC='\033[0m'

echo -e "${BOLD}╔══════════════════════════════════════════╗${NC}"
echo -e "${BOLD}║     Provider Cost Comparison             ║${NC}"
echo -e "${BOLD}╚══════════════════════════════════════════╝${NC}"
echo ""

if [ ! -f "$CONFIG" ]; then
  echo -e "${RED}Config not found: $CONFIG${NC}"
  exit 1
fi

node -e "
const fs = require('fs');
const raw = fs.readFileSync('$CONFIG', 'utf8');
const config = new Function('return (' + raw + ')')();
const providers = config.models?.providers || {};
const defaults = config.agents?.defaults || {};
const primary = typeof defaults.model === 'string' ? defaults.model : defaults.model?.primary;

// Known market rates (input $/M tokens)
const marketRates = {
  'claude-opus-4-6': 15.00,
  'claude-sonnet-4-6': 3.00,
  'claude-haiku-4-5': 0.80,
  'gpt-5.2': 2.50,
  'gpt-5.2-pro': 5.00,
  'gpt-5.2-codex': 2.50,
  'o4-mini': 1.10,
  'deepseek-v3.2': 0.27,
  'gemini-3.1-pro-preview': 1.25,
  'gemini-flash-latest': 0.10,
  'grok-4': 3.00,
  'grok-4-1-fast': 2.00,
  'grok-3-mini': 0.30,
};

// Build model→providers map
const modelProviders = {};
for (const [provName, prov] of Object.entries(providers)) {
  for (const m of (prov.models || [])) {
    const modelId = m.id;
    if (!modelProviders[modelId]) modelProviders[modelId] = [];

    const configCost = m.cost?.input || 0;
    const marketCost = marketRates[modelId] || null;

    modelProviders[modelId].push({
      provider: provName,
      fullId: provName + '/' + modelId,
      configCost,
      marketCost,
      isZero: configCost === 0,
      baseUrl: prov.baseUrl || '',
    });
  }
}

// Check for duplicates
let duplicates = 0;
let warnings = 0;

console.log('  ── Model Availability by Provider ──');
console.log('');
console.log('  ' + 'MODEL'.padEnd(25) + 'PROVIDER'.padEnd(18) + 'CONFIG \$/M'.padEnd(14) + 'MARKET \$/M'.padEnd(14) + 'STATUS');
console.log('  ' + '─'.repeat(25) + '─'.repeat(18) + '─'.repeat(14) + '─'.repeat(14) + '─'.repeat(15));

for (const [modelId, entries] of Object.entries(modelProviders).sort()) {
  for (const e of entries) {
    const isPrimary = primary === e.fullId;
    const status = [];
    if (isPrimary) status.push('▶ PRIMARY');
    if (e.isZero) status.push('FREE via proxy');
    if (e.marketCost && !e.isZero && e.configCost > 0) status.push('paid');

    console.log('  ' + modelId.padEnd(25) + e.provider.padEnd(18) + (e.isZero ? '\$0' : '\$' + e.configCost.toFixed(2)).padEnd(14) + (e.marketCost ? '\$' + e.marketCost.toFixed(2) : '?').padEnd(14) + status.join(', '));
  }

  if (entries.length > 1) {
    duplicates++;
    // Check if one is cheaper
    const costs = entries.map(e => ({ ...e, effectiveCost: e.isZero ? 0 : (e.configCost || e.marketCost || 0) }));
    costs.sort((a, b) => a.effectiveCost - b.effectiveCost);

    if (costs[0].effectiveCost < costs[costs.length - 1].effectiveCost) {
      const cheap = costs[0];
      const expensive = costs[costs.length - 1];
      console.log('  ⚠️  ' + modelId + ' is cheaper via ' + cheap.provider + ' (\$' + cheap.effectiveCost + ') vs ' + expensive.provider + ' (\$' + expensive.effectiveCost + ')');

      // Check if primary uses the expensive one
      if (primary === expensive.fullId) {
        console.log('  🔴 PRIMARY is using the MORE EXPENSIVE provider!');
        console.log('     Switch to: ' + cheap.fullId);
        warnings++;
      }
    }
  }
}

console.log('');
console.log('  ── Summary ──');
console.log('');
console.log('  Total models: ' + Object.keys(modelProviders).length);
console.log('  Across providers: ' + Object.keys(providers).length);
console.log('  Duplicate models: ' + duplicates + ' (same model, multiple providers)');

if (warnings > 0) {
  console.log('');
  console.log('  🔴 ' + warnings + ' routing warning(s) — you may be paying for something available cheaper');
} else if (duplicates > 0) {
  console.log('  ✅ No routing issues — cheapest provider is being used');
} else {
  console.log('  ✅ No duplicate models found — each model has one provider');
}

// Check for proxy indicator
const proxyProviders = Object.entries(providers).filter(([_, p]) => p.baseUrl && !p.baseUrl.includes('openrouter') && !p.baseUrl.includes('anthropic.com') && !p.baseUrl.includes('openai.com'));
if (proxyProviders.length > 0) {
  console.log('');
  console.log('  ℹ️  Detected proxy provider(s): ' + proxyProviders.map(([n]) => n).join(', '));
  console.log('     If costs show \$0, the proxy handles billing separately.');
  console.log('     Check your proxy dashboard for actual costs.');
}
" 2>/dev/null

